snippet_css:
:root{
  --bg: #E1F5FE;
  --fg: #0B2A66;
  --muted: #3D5687;
  --surface: #F7FBFF;
  --border: #9FC6F0;
  --accent: #D10070;
  --accent-fg: #FFFFFF;
  --radius: 20px;
  --radius-sm: 12px;
  --shadow: 0 8px 0 rgba(11,42,102,.10),0 14px 30px rgba(0,102,255,.16);
  --btn-shadow: 0 4px 0 rgba(157,0,83,.45);
  --art-bg: linear-gradient(180deg,#9FD8FF,#E1F5FE 40%,#FFE0F0);
  --media-bg: linear-gradient(160deg,#CBE6FF,#FFE0F0 60%,#E9E0FF);
  --cta-bg: #EAF7FF;
  --input-bg: #FFFFFF;
  --ok: #0E7A46;
  --warn: #A61C4E;
  --font-display: Syne,'Noto Sans TC',sans-serif;
  --font-body: Inter,'Noto Sans TC',sans-serif;
  --font-mono: Syne,ui-monospace,monospace;
  --focus-ring: var(--accent);
}

